#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Merge branches in order; generated files that conflict are regenerated, hand-written ones stop the merge (jam/merge_branches.sh BASE branch ...).

  jam/merge_branches.sh [options] BASE branch [branch ...]
  jam/merge_branches.sh --continue BASE [branch ...]        finish the merge a stop left in progress (you resolved the hand-written files), then go on

For every branch: `git merge --no-ff --no-commit`. A conflict in a GENERATED file takes our side as a placeholder and is regenerated after the merge by the
tool that makes it (below); a conflict in any other file stops everything, with the merge left in progress and the list of those files (resolve them, git add,
then --continue). When all merges are done: `jam/check.sh --changed BASE`. HEAD is not moved: check out the branch you integrate on first; BASE is
the commit it started from (what --changed compares with).

  generated file                                         regenerated by
  felucca-base/firmware/src/jrny_ctx.h                   tests/jrny_ctx.c ("jrny_ctx gen", compiled as host_tests.sh jrnyctx does)
  felucca-base/tools/factory_multis/M*.bin               tools/factory_multis.py build
  felucca-base/tools/drone_multis/M*.bin                 tools/drone_pack.py
  felucca-base/tests/{golden,multi_render_golden,union_golden}.txt   GOLDEN_UPDATE=1 / MULTI_RENDER_UPDATE=1 on regress / mrender / union (rows that changed are counted)
  felucca-base/build/gen/*                               tools/build.py --gen-only (never tracked: always rebuilt before the tools run)

options: --no-check (skip check.sh), --hand-from REF (hand-written conflicts take REF's file instead of stopping: replays a finished integration), --dry (list only)
"""
import fnmatch, os, re, subprocess, sys

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.dirname(HERE)
FB = os.path.join(REPO, "felucca-base")

KINDS = [  # (name, glob patterns, order)
    ("bins", ["felucca-base/tools/factory_multis/M[0-9][0-9].bin"]),
    ("drones", ["felucca-base/tools/drone_multis/M[0-9][0-9].bin"]),
    ("jrny", ["felucca-base/firmware/src/jrny_ctx.h"]),
    ("golden", ["felucca-base/tests/golden.txt"]),
    ("mrender", ["felucca-base/tests/multi_render_golden.txt"]),
    ("union", ["felucca-base/tests/union_golden.txt"]),
]


def git(*a, check=True):
    p = subprocess.run(["git", *a], cwd=REPO, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    if check and p.returncode != 0:
        sys.exit("merge_branches: git %s failed:\n%s" % (" ".join(a), p.stdout[-1500:]))
    return p


def sh(cmd, cwd=None, env=None):
    p = subprocess.run(cmd, cwd=cwd or REPO, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, env=env)
    if p.returncode != 0:
        sys.exit("merge_branches: %s failed:\n%s" % (" ".join(cmd) if isinstance(cmd, list) else cmd, p.stdout[-2000:]))
    return p.stdout


def kind_of(path):
    for k, pats in KINDS:
        if any(fnmatch.fnmatch(path, p) for p in pats):
            return k
    return None


def conflicts():
    return [f for f in git("diff", "--name-only", "--diff-filter=U").stdout.split("\n") if f]


def regen(kinds, env0):
    """regenerate the given kinds, in dependency order; -> {kind: note}."""
    notes = {}
    py = sys.executable
    env = dict(os.environ, HT_REALCC=env0)
    sh([py, "tools/build.py", "--gen-only"], FB)
    if "bins" in kinds:
        sh([py, "tools/factory_multis.py", "build"], FB)
        sh([py, "tools/build.py", "--gen-only"], FB)
        notes["bins"] = "tools/factory_multis.py build"
    if "drones" in kinds:
        sh([py, "tools/drone_pack.py"], FB)
        sh([py, "tools/build.py", "--gen-only"], FB)
        notes["drones"] = "tools/drone_pack.py"
    if "jrny" in kinds:
        subprocess.run(["sh", "host_tests.sh", "jrnyctx"], cwd=REPO, env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)   # (builds build/host/jrny_ctx; the group may FAIL on the placeholder: that is why)
        out = subprocess.run(["sh", "-c", "build/host/jrny_ctx gen > firmware/src/jrny_ctx.h.new && mv firmware/src/jrny_ctx.h.new firmware/src/jrny_ctx.h"], cwd=FB,
                             stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, env=env)
        if out.returncode != 0:
            sys.exit("merge_branches: jrny_ctx gen failed:\n" + out.stdout[-1500:])
        notes["jrny"] = "jrny_ctx gen"
    for k, grp, var, f in (("golden", "regress", "GOLDEN_UPDATE", "felucca-base/tests/golden.txt"),
                           ("mrender", "mrender", "MULTI_RENDER_UPDATE", "felucca-base/tests/multi_render_golden.txt"),
                           ("union", "union", "GOLDEN_UPDATE", "felucca-base/tests/union_golden.txt")):
        if k in kinds:
            before = open(os.path.join(REPO, f), newline="").read().split("\n")
            subprocess.run(["sh", "host_tests.sh", grp], cwd=REPO, env=dict(env, **{var: "1"}), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            after = open(os.path.join(REPO, f), newline="").read().split("\n")
            notes[k] = "%s=1 on %s: %d rows differ from our side" % (var, grp, len(set(after) ^ set(before)) // 2)
    return notes


def main():
    args = sys.argv[1:]
    opt = {"--no-check": False, "--dry": False, "--continue": False}
    hand_from = None
    rest = []
    i = 0
    while i < len(args):
        a = args[i]
        if a in opt:
            opt[a] = True
        elif a == "--hand-from":
            hand_from = args[i + 1]; i += 1
        else:
            rest.append(a)
        i += 1
    if not rest or (len(rest) < 2 and not opt["--continue"]):
        sys.exit(__doc__)
    base, branches = rest[0], rest[1:]
    cc = subprocess.run(["sh", "-c", "command -v cc"], stdout=subprocess.PIPE, text=True).stdout.strip()
    if not opt["--continue"] and git("status", "--porcelain", "--untracked-files=no").stdout.strip():
        sys.exit("merge_branches: the working tree has uncommitted changes; commit or clean them first")
    log = []
    merging = os.path.exists(os.path.join(REPO, ".git")) and git("rev-parse", "-q", "--verify", "MERGE_HEAD", check=False).returncode == 0
    todo = list(branches)
    if opt["--continue"]:
        if not merging:
            sys.exit("merge_branches: no merge in progress")
        left = conflicts()
        if left:
            sys.exit("merge_branches: still unresolved: " + " ".join(left))
        gen = [l for l in open(stopfile()).read().split("\n") if l] if os.path.exists(stopfile()) else []
        finish(None, gen, cc, log)
    for br in todo:
        print("== merge %s" % br, flush=True)
        if opt["--dry"]:
            continue
        p = git("merge", "--no-ff", "--no-commit", br, check=False)
        cf = conflicts()
        if p.returncode != 0 and not cf:
            sys.exit("merge_branches: merge %s failed without conflicts:\n%s" % (br, p.stdout[-1000:]))
        gen = [f for f in cf if kind_of(f)]
        hand = [f for f in cf if not kind_of(f)]
        for f in gen:                                   # a placeholder: our side; regenerated below
            git("checkout", "--ours", "--", f)
            git("add", "--", f)
        if hand and hand_from:
            for f in hand:
                git("checkout", hand_from, "--", f)
            hand = []
        if hand:
            print("== STOPPED at %s: hand-written files conflict (resolve, git add, then jam/merge_branches.sh --continue %s ...):" % (br, base))
            for f in hand:
                print("   " + f)
            if gen:
                print("   (generated, to be regenerated after you continue: %s)" % " ".join(gen))
            open(stopfile(), "w").write("\n".join(gen))
            sys.exit(2)
        finish(br, gen, cc, log)
    if opt["--dry"]:
        return 0
    for ln in log:
        print(ln)
    if opt["--no-check"]:
        return 0
    print("== jam/check.sh --changed %s" % base, flush=True)
    return subprocess.run(["sh", "jam/check.sh", "--changed", base], cwd=REPO).returncode


def stopfile():
    return os.path.join(REPO, git("rev-parse", "--git-dir").stdout.strip(), "merge_branches.gen")


def finish(br, gen, cc, log):
    """regenerate what conflicted, commit the merge."""
    kinds = {kind_of(f) for f in gen}
    notes = regen(kinds, cc) if kinds else {}
    for f in gen:
        git("add", "--", f)
    if kinds:                                           # (the regenerators wrote their files: stage every tracked file they changed)
        git("add", "-u")
    msg = "Merge %s" % (br or "branch (continued)")
    if notes:
        msg += "; regenerated: " + ", ".join("%s (%s)" % (k, v) for k, v in sorted(notes.items()))
    try:
        os.unlink(stopfile())
    except OSError:
        pass
    git("commit", "-q", "-m", msg + "\n\nCo-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>")
    log.append("merged %s: %s" % (br, "; ".join("%s: %s" % kv for kv in sorted(notes.items())) or "no generated-file conflict"))


if __name__ == "__main__":
    sys.exit(main())
